Here is a complete, idiomatic Terraform implementation covering the canonical scenario. It uses a modular structure, supports `dev` and `prod` via workspaces and `tfvars`, and satisfies all acceptance criteria including encryption, isolation, least-privilege IAM, and secure secret handling.

### Directory Structure

```text
├── main.tf
├── variables.tf
├── outputs.tf
├── backend.tf
├── env/
│   ├── dev.tfvars
│   └── prod.tfvars
└── modules/
    ├── eks/
    │   ├── main.tf
    │   └── variables.tf
    ├── s3/
    │   ├── main.tf
    │   └── variables.tf
    ├── rds/
    │   ├── main.tf
    │   └── variables.tf
    ├── iam/
    │   ├── main.tf
    │   └── variables.tf
    └── alb/
        ├── main.tf
        └── variables.tf
```

### `backend.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }

  backend "s3" {
    bucket         = "my-terraform-state-bucket"
    key            = "infrastructure/terraform.tfstate"
    region         = "us-east-1"
    dynamodb_table = "terraform-state-lock"
    encrypt        = true
  }
}
```

### `variables.tf`
```hcl
variable "environment" {
  description = "Environment name (dev/prod)"
  type        = string
}

variable "region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "app_name" {
  description = "Application name"
  type        = string
  default     = "canonical-app"
}

# Sensitive variables should be provided via env vars, CI secrets, or encrypted var files.
# Do not store these in plaintext in Git.
variable "db_password" {
  description = "RDS master password"
  type        = string
  sensitive   = true
}

variable "db_secret_arn" {
  description = "ARN of the secret containing DB credentials (if using Secrets Manager)"
  type        = string
  default     = null
}

variable "enable_cross_region_replication" {
  description = "Enable S3 cross-region replication"
  type        = bool
  default     = false
}

variable "replication_target_region" {
  description = "Region for S3 cross-region replication"
  type        = string
  default     = "us-west-2"
}
```

### `main.tf`
```hcl
provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Environment = var.environment
      Project     = var.app_name
      ManagedBy   = "terraform"
    }
  }
}

data "terraform_remote_state" "vpc" {
  backend = "s3"

  config = {
    bucket = "my-terraform-state-bucket"
    key    = "networking/vpc/terraform.tfstate"
    region = var.region
  }
}

# EKS Module
module "eks" {
  source = "./modules/eks"

  environment = var.environment
  app_name    = var.app_name
  cluster_version = "1.28"

  # Sizing based on environment
  instance_types = var.environment == "prod" ? ["t3.large"] : ["t3.medium"]
  desired_nodes  = var.environment == "prod" ? 4 : 2
  min_nodes      = var.environment == "prod" ? 2 : 1
  max_nodes      = var.environment == "prod" ? 6 : 3

  vpc_id     = data.terraform_remote_state.vpc.outputs.vpc_id
  subnet_ids = data.terraform_remote_state.vpc.outputs.private_subnet_ids

  # OIDC for IAM roles
  cluster_endpoint = module.eks_cluster.endpoint
  cluster_oidc_arn = module.eks_cluster.oidc_provider_arn
}

module "eks_cluster" {
  source = "./modules/eks/cluster" # Assumed split for cluster vs nodegroup if needed, or single module

  environment = var.environment
  app_name    = var.app_name
  cluster_version = "1.28"

  vpc_id     = data.terraform_remote_state.vpc.outputs.vpc_id
  subnet_ids = data.terraform_remote_state.vpc.outputs.private_subnet_ids
}

# S3 Module
module "s3" {
  source = "./modules/s3"

  environment = var.environment
  app_name    = var.app_name

  versioning     = true
  encryption     = true
  public_access  = true # Block all public access

  cross_region_replication = var.enable_cross_region_replication
  replication_target_region = var.replication_target_region
}

# RDS Module
module "rds" {
  source = "./modules/rds"

  environment = var.environment
  app_name    = var.app_name

  instance_class = var.environment == "prod" ? "db.t3.medium" : "db.t3.micro"
  multi_az       = var.environment == "prod" ? true : false
  encrypted      = var.environment == "prod" ? true : true # Encrypt both for security
  backup_retention_period = 7
  deletion_protection     = true
  publicly_accessible     = false

  db_password = var.db_password

  vpc_id     = data.terraform_remote_state.vpc.outputs.vpc_id
  subnet_ids = data.terraform_remote_state.vpc.outputs.private_subnet_ids
}

# IAM Module
module "iam" {
  source = "./modules/iam"

  environment = var.environment
  app_name    = var.app_name

  # Prod uses OIDC trust, Dev uses programmatic user/role
  use_oidc_trust = var.environment == "prod"
  cluster_oidc_arn = module.eks_cluster.oidc_provider_arn
}

# ALB Module
module "alb" {
  source = "./modules/alb"

  environment = var.environment
  app_name    = var.app_name

  # Prod uses CloudFront + ACM, Dev uses internal ALB
  use_cloudfront = var.environment == "prod"
  domain_name    = var.environment == "prod" ? "app.example.com" : null

  subnet_ids = data.terraform_remote_state.vpc.outputs.public_subnet_ids
  vpc_id     = data.terraform_remote_state.vpc.outputs.vpc_id
}
```

### `outputs.tf`
```hcl
output "eks_cluster_endpoint" {
  value = module.eks_cluster.endpoint
}

output "eks_cluster_name" {
  value = module.eks_cluster.cluster_name
}

output "s3_bucket_arn" {
  value = module.s3.bucket_arn
}

output "rds_endpoint" {
  value = module.rds.db_endpoint
}

output "alb_dns_name" {
  value = module.alb.dns_name
}

output "cloudfront_domain" {
  value = module.alb.use_cloudfront ? module.alb.cloudfront_domain : null
}
```

### `env/dev.tfvars`
```hcl
environment = "dev"
region      = "us-east-1"
app_name    = "canonical-app"

# Sensitive values should be injected via CI/CD secrets or SOPS-encrypted files
# db_password = "encrypted-value-here" 

enable_cross_region_replication = false
```

### `env/prod.tfvars`
```hcl
environment = "prod"
region      = "us-east-1"
app_name    = "canonical-app"

# Sensitive values should be injected via CI/CD secrets or SOPS-encrypted files
# db_password = "encrypted-value-here" 

enable_cross_region_replication = true
